'use strict';
//
// File: model_tables.ts
//
// ---------------------------------------------------------------------------
// THE TABLES THE SERVICE READS FROM THE ABSTRACT MODEL (#1390).
//
// A directory object written in TypeSpec has its table generated by the image
// build, into `models/generated/`. A module that owns such an object reads
// its table here, once, when it loads. `common/compiled_tree.js` refuses a
// tree without the files, so a missing one has already been explained by the
// time this runs.
//
// A LEAF. It requires nothing of this service, so it can be required from
// anywhere without moving a route or closing a cycle.
// ---------------------------------------------------------------------------

import fs = require('fs');
import path = require('path');
import bunyan = require('bunyan');

const log = bunyan.createLogger({
  name: 'sts-model-tables',
  level: process.env.LOG_LEVEL || process.env.STS_LOG_LEVEL || 'info'
});

/**
 * Reads generated tables.
 */
class ModelTables {
  /**
   * One object's table. A module may add to what it gets, as
   * `common/applications.js` adds each row's `editable`, so each caller has
   * its own copy.
   *
   * @param id - the object id, such as `application`
   * @returns the table
   */
  static schema(id: string): any {
    log.debug("Entering ModelTables.schema().");
    const table = JSON.parse(fs.readFileSync(path.join(__dirname, '..',
      'models', 'generated', id + '.schema.json'), 'utf8'));
    log.debug("Leaving ModelTables.schema().");
    return table;
  }

  /**
   * A policy's settings: what `FIELDS` holds. What the code computes, such
   * as a limit `common/crypto.js` owns, is passed in by the row's key, so
   * there is one writing of it.
   *
   * @param id - the object id, such as `policy.password`
   * @param bound - by row key, the values the code computes
   * @param computed - rows the code builds whole, and the key they go before
   * @returns the rows
   */
  static fields(id: string, bound?: Record<string, object>,
      computed?: { before: string; rows: any[] }): any[] {
    log.debug("Entering ModelTables.fields().");
    const rows = ModelTables.read(id).fields.map(function (row: any) {
      return Object.assign(row, (bound || {})[row.key]);
    });
    if (computed) {
      const at = rows.findIndex(function (row: any) {
        return row.key === computed.before;
      });
      rows.splice(at, 0, ...computed.rows);
    }
    log.debug("Leaving ModelTables.fields().");
    return rows;
  }

  /**
   * How people and groups name a policy: what `SELECTORS` holds.
   *
   * @param id - the object id
   * @returns the rows
   */
  static selectors(id: string): { key: string; attribute: string;
      what: string }[] {
    log.debug("Entering ModelTables.selectors().");
    const rows = ModelTables.read(id).selectors;
    log.debug("Leaving ModelTables.selectors().");
    return rows;
  }

  /**
   * The directory's name lists: the canonical spellings and the attributes
   * withheld from every reader.
   *
   * @returns standard, own and secret
   */
  static names(): { standard: string[]; own: string[]; secret: string[] } {
    log.debug("Entering ModelTables.names().");
    const lists = ModelTables.file('directory.names.json');
    log.debug("Leaving ModelTables.names().");
    return lists;
  }

  /**
   * What an object states about itself beyond its rows: its key, its filing
   * name, the closed lists its module reads.
   *
   * @param id - the object id
   * @returns the facts, empty when it states none
   */
  static facts(id: string): any {
    log.debug("Entering ModelTables.facts().");
    const facts = ModelTables.file('directory.facts.json')[id] || {};
    log.debug("Leaving ModelTables.facts().");
    return facts;
  }

  /**
   * Every reference between directory objects.
   *
   * @returns one row per link
   */
  static links(): any[] {
    log.debug("Entering ModelTables.links().");
    const links = ModelTables.file('directory.links.json');
    log.debug("Leaving ModelTables.links().");
    return links;
  }

  /**
   * One generated file, parsed.
   *
   * @param name - its name under `models/generated`
   * @returns the value
   */
  static file(name: string): any {
    log.debug("Entering ModelTables.file().");
    const value = JSON.parse(fs.readFileSync(path.join(__dirname, '..',
      'models', 'generated', name), 'utf8'));
    log.debug("Leaving ModelTables.file().");
    return value;
  }

  /**
   * One object's generated settings file.
   *
   * @param id - the object id
   * @returns its fields and selectors
   */
  static read(id: string): any {
    log.debug("Entering ModelTables.read().");
    const declared = JSON.parse(fs.readFileSync(path.join(__dirname, '..',
      'models', 'generated', id + '.fields.json'), 'utf8'));
    log.debug("Leaving ModelTables.read().");
    return declared;
  }
}

export = ModelTables;
